// Extract sender email and message details
const email = $input.first().json;

const senderEmail = email.from?.value?.[0]?.address 
  || email.from 
  || '';

const subject = email.subject || '';
const snippet = email.snippet || email.text?.substring(0, 200) || '';
const messageId = email.id || '';
const threadId = email.threadId || '';

// Clean sender email
const cleanSender = senderEmail.toLowerCase().trim();

if (!cleanSender) {
  throw new Error('Could not extract sender email from: ' + JSON.stringify(email.from));
}

return [{
  json: {
    sender_email: cleanSender,
    subject: subject,
    snippet: snippet.substring(0, 200),
    message_id: messageId,
    thread_id: threadId,
    received_at: new Date().toISOString()
  }
}];

// Merge lead data with incoming email data
const leadRow = $input.first().json;
const emailData = $('Extract Email Sender Info').first().json;

return [{
  json: {
    // Lead data from sheet
    company_name: leadRow.company_name,
    contact_email: leadRow.contact_email,
    website: leadRow.website,
    your_service: leadRow.your_service,
    sent_at: leadRow.sent_at,

    // Reply data
    reply_subject: emailData.subject,
    reply_snippet: emailData.snippet,
    reply_at: emailData.received_at,
    message_id: emailData.message_id
  }
}];

