// Extract and decode tracking ID from URL query param
const query = $input.first().json.query;
const trackingId = query?.id || '';

if (!trackingId) {
  return [{ json: { error: 'No tracking ID', email: null } }];
}

// Decode base64 to get email
let email = '';
try {
  email = Buffer.from(trackingId, 'base64').toString('utf-8');
} catch(e) {
  // Try URL decode first then base64
  try {
    email = Buffer.from(decodeURIComponent(trackingId), 'base64').toString('utf-8');
  } catch(e2) {
    email = trackingId; // fallback — use as-is
  }
}

// Basic email validation
const isValidEmail = email.includes('@') && email.includes('.');

return [{
  json: {
    tracking_id: trackingId,
    contact_email: isValidEmail ? email.toLowerCase().trim() : null,
    opened_at: new Date().toISOString(),
    valid: isValidEmail
  }
}];

// Build update data — increment open count
const leadRow = $input.first().json;
const trackData = $('Decode Tracking ID').first().json;

// Get current open count and increment
const currentCount = parseInt(leadRow.open_count || '0') || 0;
const newCount = currentCount + 1;

// First open vs repeat open
const isFirstOpen = currentCount === 0;

return [{
  json: {
    company_name: leadRow.company_name || 'Unknown',
    contact_email: trackData.contact_email,
    your_service: leadRow.your_service || '',
    email_opened: 'TRUE',
    opened_at: isFirstOpen ? trackData.opened_at : leadRow.opened_at,
    last_opened_at: trackData.opened_at,
    open_count: newCount.toString(),
    is_first_open: isFirstOpen,
    status: leadRow.status || 'sent'
  }
}];

