// Filter only pending rows
const items = $input.all();

const filtered = items.filter(item => {
  const status = (item.json.status || '').toLowerCase().trim();
  // Accept pending or empty status
  return status === 'pending' || status === '';
});

if (filtered.length === 0) {
  return [{ json: { no_leads: true } }];
}

// Return all filtered items — n8n processes each separately
return filtered.map(item => ({ json: item.json }));

// ONE NODE: Scrape + Clean + Skip check
// This fixes the $input.first() vs .item issue
// by doing everything in one node

const lead = $input.first().json;

// Clean email (remove spaces)
const cleanEmail = (lead.contact_email || '').trim();

// Validate email
if (!cleanEmail || !cleanEmail.includes('@')) {
  return [{ json: { skip: true, reason: 'Invalid email: ' + cleanEmail } }];
}

// Scrape website using ScrapingBee
let websiteText = '';
try {

  const scrapeUrl = `https://api.scrapingant.com/v2/general?url=${encodeURIComponent(lead.website)}&x-api-key=f435ff2289f643e582dc359d5576e6b1`;


  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: scrapeUrl,
    timeout: 15000
  });

  const rawText = typeof response === 'string'
    ? response
    : JSON.stringify(response);

  websiteText = rawText
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 3000);

} catch(e) {
  websiteText = 'Website content not available';
}

return [{
  json: {
    company_name: lead.company_name,
    website: lead.website,
    contact_email: cleanEmail,
    your_service: lead.your_service,
    sender_name: 'Umar',
    website_content: websiteText,
    scrape_success: websiteText.length > 50
  }
}];

const geminiResponse = $input.first().json;
const rawText = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text || '';
const leadData = $('Scrape + Clean Website').first().json;

let emailContent;
try {
  const cleaned = rawText
    .replace(/```json/g, '')
    .replace(/```/g, '')
    .trim();
  emailContent = JSON.parse(cleaned);
} catch(e) {
  emailContent = {
    subject: `Quick question about ${leadData.company_name}`,
    body: `Hi,\n\nSaw what you're doing at ${leadData.company_name} — impressive work.\n\n${leadData.your_service} could be a strong fit.\n\nWorth a 15-min chat?\n\n${leadData.sender_name}`,
    personalization_used: 'Fallback'
  };
}

// Remove ALL placeholders — safety net
let cleanBody = (emailContent.body || '')
  .replace(/\[Your Name\]/gi, leadData.sender_name)
  .replace(/\[Name\]/gi, leadData.sender_name)
  .replace(/\[name\]/gi, leadData.sender_name)
  .replace(/\[Sender\]/gi, leadData.sender_name)
  .replace(/\[Your name\]/gi, leadData.sender_name)
  .replace(/\[.*?\]/g, leadData.sender_name);

// Tracking pixel
const trackingId = Buffer.from(leadData.contact_email).toString('base64');
const pixelUrl = `https://umarimran99999.app.n8n.cloud/webhook/track-open?id=${trackingId}`;

// HTML email with pixel
const htmlBody = `<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.8;color:#333;max-width:600px;">
${cleanBody.replace(/\n/g, '<br>')}
</div>
<img src="${pixelUrl}" width="1" height="1" style="display:none;" border="0" alt="" />`;

return [{
  json: {
    ...leadData,
    email_subject: emailContent.subject || `Quick question — ${leadData.company_name}`,
    email_body: htmlBody,
    tracking_id: trackingId,
    personalization_used: emailContent.personalization_used || '',
    generated_at: new Date().toISOString()
  }
}];

const items = $input.all();
const now = new Date();
const threeDaysMs = 3 * 24 * 60 * 60 * 1000;

const due = items.filter(item => {
  const row = item.json;
  const status = (row.status || '').toLowerCase().trim();
  const fu1 = (row.follow_up_1_sent || '').toString().toLowerCase();
  const replied = (row.reply_received || '').toString().toLowerCase();

  if (status !== 'sent') return false;
  if (fu1 === 'true') return false;
  if (replied === 'true') return false;
  if (!row.sent_at) return false;

  return (now - new Date(row.sent_at)) >= threeDaysMs;
});

if (due.length === 0) {
  return [{ json: { no_followups: true } }];
}

return due.map(item => ({ json: item.json }));

const items = $input.all();
const now = new Date();
const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;

const due = items.filter(item => {
  const row = item.json;
  const status = (row.status || '').toLowerCase().trim();
  const fu1 = (row.follow_up_1_sent || '').toString().toLowerCase();
  const fu2 = (row.follow_up_2_sent || '').toString().toLowerCase();
  const replied = (row.reply_received || '').toString().toLowerCase();

  if (status !== 'sent') return false;
  if (fu1 !== 'true') return false;
  if (fu2 === 'true') return false;
  if (replied === 'true') return false;
  if (!row.sent_at) return false;

  return (now - new Date(row.sent_at)) >= sevenDaysMs;
});

if (due.length === 0) {
  return [{ json: { no_followups: true } }];
}

return due.map(item => ({ json: item.json }));

